import pathlib,json,hashlib,datetime,resource,subprocess,os,time
resource.setrlimit(resource.RLIMIT_CPU,(120,120));resource.setrlimit(resource.RLIMIT_AS,(6*1024**3,6*1024**3))
os.sched_setaffinity(0,set(sorted(os.sched_getaffinity(0))[:2]))
P=pathlib.Path(__file__).resolve().parent; start=time.monotonic();sha=lambda b:hashlib.sha256(b).hexdigest(); now=lambda:datetime.datetime.now(datetime.timezone.utc).isoformat()
d=json.loads((P/'audited-extraction.json').read_text())
notes={
'324501':('PARK_NO_FULL_ROUTE','Equitable coloring minima are not monotone in the number of colors. Ordinary Brooks coloring does not ensure equitable classes. No equitable recoloring invariant closing arbitrary connected graphs obtained.','A proof must control all class sizes while preserving properness; complete bipartite exceptions to an equitable Delta coloring do not automatically refute the minimum equitable chromatic-number bound.'),
'324540':('PARK_FLAGSHIP','No route beyond the source-reported broken-circuit complete-intersection class. Quadraticity alone is not Koszulness; special matroid classes cannot prove the equivalence.','General converse Koszul implies supersolvable, with field/arrangement conventions fixed; no primary-body clearance or complete algebraic proof.'),
'324588':('PARK_SUSTAINED_GAPS','Three attempts: phantom first move, one-element repair, and finite-board stabilization. Each fails for a specific reason in MECHANISMS.md. Both arXiv versions read at definitions and concluding conjecture.','Uniform strategy coupling independent of k, or a proved unbounded amplification family. A fixed finite board cannot refute existence of some universal c.'),
'324627':('EXCLUDE_ROUTINE_CLASSICAL_BRIDGE','Complete signed-difference plus rational-kernel proof in MECHANISMS.md. Read Definitions 5.7–5.17 and Conjecture 5.20. Integer cycle requirement explicitly discharged.','No mathematical ordinary gap for finite networks under the source definition. Lean absent; not eligible for credit because this is a routine rational linear-algebra reduction.'),
'324706':('PARK_FLAGSHIP','The literal claim quantifies over all finite graphs with an edge. No reduction removing the bipartite union-closed obstruction found.','A universal proof of the equivalent Frankl formulation, or a genuine finite counterexample, not the already covered non-bipartite class.'),
'324757':('PARK_SUSTAINED_GAPS','Read entire arXiv v1 and published CAI body. Parseval, completing one zero-free balanced Boolean component, and power-spectrum reduction examined; none settles all nonzero lambda simultaneously.','A characteristic-two permutation with every off-axis Walsh coefficient nonzero, or a universal vanishing proof. Odd-characteristic/domain corrections are excluded.'),
'324769':('PARK_FLAGSHIP','No general biclique-cover mechanism. The r=1 literal endpoint is a zero-credit endpoint correction. Upstream catalogue Ryser hypergraph counterexamples do not by themselves establish the distinct 2r−2 biclique bound fails.','Need actual component-cover formulation and full range r≥2; no automatic transfer from a related Ryser construction.'),
'335118':('PARK_NO_FULL_ROUTE','Uniform clique weights yield the lower bound, not the upper bound for arbitrary extra vertices. Symmetrizing extra vertices requires justified link comparisons.','Control all outside weight mass and all r≥3 in the full binomial edge interval; no single r or restricted support credit.'),
'339208':('PARK_FLAGSHIP','Bipartite double-cover/entropy route does not automatically bound arbitrary regular graph colorings. Cases d=3,4 cannot settle all d and q.','A full comparison theorem for all regular graphs, not a bipartite or low-degree case.'),
'351163':('PARK_NO_FULL_ROUTE','A path realizes the stated exception, and the record says cactus graphs are already covered. No inequality controlling cycles and degree redistribution for all connected graphs found.','Primary graph connectivity/domain conventions and full non-cactus lower bound. Disconnected or undefined-radius wording is not a candidate.'),
'355928':('EXCLUDE_ROUTINE_COMPLETE_GRAPH_SPECIALIZATION','Complete K4[K2]=K8 counterexample and explicit edge labeling in MECHANISMS.md. Same-source constructions read; accepted local-antimagic families 354228 and 365453 explicitly checked.','No ordinary gap in this counterexample. Complete-graph specialization earns zero significance credit; journal/corrections not fully read.'),
'368224':('PARK_SOURCE_STATUS_MISMATCH','Read v1 and latest v3 distinction: spread-out conjecture is still described as wide open; the refuted claim is the different acyclic-system conjecture. v2 cached and relevant distinction checked.','Actual spread-out capacity condition and arbitrary-dimensional tiling completion; no transfer from acyclic-system counterexample. MathDB references misidentify the refuted conjecture.'),
'369613':('PARK_SOURCE_DEFINITION_MISMATCH','Read latest source definition: reduced means no equal open neighborhoods and no isolated vertices. MathDB substitutes a rank-deletion condition. Latest v3 Conjecture 2.1 retains m(r); 2026 inertia counterexample addresses a different inequality.','No proof/refutation of order-versus-rank bound. No retraction established by consulted pages; journal/correction sweep incomplete. No exploit of malformed literal definition.'),
'372699':('PARK_FLAGSHIP','No complete analytic comparison of moduli spaces, orientations, compactification or chain maps. Metadata does not determine chain-level versus induced equality.','Actual Floer definitions and a full comparison theorem; no source-body review or formalization route.'),
'373017':('PARK_PARTIAL_RESULTS_ALREADY_PUBLISHED','Read all three versions at type definition/conjecture/main theorems. Latest Theorem A proves coprime-to-six case; later theorems cover additional cases. Cyclic relation-matrix determinant gives a finite counterexample test, but none computed.','All remaining n, especially factors 2 and 3 mixed with odd factors. Partial classification is not a full solution. Need cyclic-presentation-to-abelianization bridge for any certificate.'),
'373849':('PARK_FLAGSHIP','No full embedding construction satisfying both sharpness and type A2. Ordinary Boone–Higman statements cannot replace the relative permutational quantifiers.','Actual normal-pair/action definitions and a universal finitely generated solvable-word-problem construction; no body review.'),
'374045':('PARK_GEOMETRIC_BRIDGE','Hecke word counts alone do not compute a scheme-theoretic coherent Euler characteristic. Flatness/degeneration not justified. Registry Brill–Noether graph module routes to a different graph-divisor problem.','Geometric degeneration and flatness for the literal transmission loci; no low-genus or combinatorial word-count substitute.'),
'374075':('EXCLUDE_PUBLIC_REFUTATION','Read current source Section 3.3, Conjecture 3.3 and Theorem 3.4 proof: explicit modified 7-regular poset on 34 points has 260553 ideals and 131576429145341435860520294400 linear extensions; tower has 262143 sets and fewer chains. Padding the ideal family reaches exact cardinality without losing chains.','No eligible new mechanism: printed object/construction already refutes the stated extremal claim. Full independent numeric recount and Lean were not run.'),
'375087':('PARK_FLAGSHIP_MISSING_HYPOTHESES','Literal statement begins with an unresolved theorem-assumption reference. No full Weyl-relation/self-adjoint-extension route.','Recover all source hypotheses and domains; scalar or finite-dimensional cancellation examples alone do not settle full scope.'),
'375537':('CONDITIONAL_PI_CERTIFICATE_PLAN_NO_WITNESS','Sustained integer-lift analysis; fiber connectivity is already Esperet et al. Lemma 5.5. Exact quotient-edge cut-certificate design in MECHANISMS.md includes all up-to-four integer shifts.','Find an actual graph/modulus for which modular graph is connected and integer-lift quotient is disconnected, or prove missing edge lifting globally. No witness, no executable search run, no credit; Pi awaits root.')}
prefix={'324588':['tau','tau-v1','tau-journal-public'],'324627':['maxflow'],'324757':['field','field-journal'],'355928':['product'],'368224':['spread','spread-v1','spread-v2','spread-v3'],'369613':['reduced','reduced-v1','reduced-v2','reduced-v3','inertia-citing'],'373017':['group','group-v1','group-v2','group-v3'],'374075':['tower','tower-v1'],'375537':['flow','flow-original','flow-original-v1','flow-original-v2','flow-original-v3']}
for k,v in d.items():
 status,attempt,gap=notes[k];v.update(disposition=status,accepted_credit=0,ordinary_attempts=attempt,remaining_lemmas_or_limits=gap)
 v['raw_provenance']['literal_raw_file']=str(P/'raw'/f'{k}.jsonl');v['raw_provenance']['literal_raw_utf8']=(P/'raw'/f'{k}.jsonl').read_bytes().decode()
 v['review_depth']={'literal_statement_read':True,'metadata_read':True,'historical_search':v.pop('history'),'primary_body_read':k in prefix,'primary_read_scope':attempt if k in prefix else 'No primary body read. Statement-only mathematical screening; parked without novelty or source qualification.','primary_text_files':[str(P/'sources'/f'{x}.txt') for x in prefix.get(k,[]) if (P/'sources'/f'{x}.txt').exists()],'full_all_version_proof_audit':False,'journal_corrections_withdrawal_clearance':'Incomplete; no clearance claimed','source_figures_visual_review':'Not visually audited; no new finite witness claimed','independent_review':False,'lean_execution':False}
 v['prior_status']='All project historical ID/title/exact-source-family text matches searched; see historical-context-'+k+'.txt and limits. Presence in routing and raw corpus is not an earlier technical review or novelty clearance.'
 v['source_inventory']='source-read-inventory.json; fetch-receipts.jsonl; search1.json–search3.json (search routing, not proof evidence)'
