(P/'results.json').write_text(json.dumps(d,indent=2,ensure_ascii=False)+'\n')
# Convert every cached PDF under explicit limits, retaining stderr and a command receipt.
logs=[]
for f in (P/'sources').glob('*.pdf'):
 if not f.read_bytes().startswith(b'%PDF'):continue
 target=f.with_suffix('.txt');cp=subprocess.run(['pdftotext','-layout',str(f),str(target)],capture_output=True,timeout=15)
 logs.append({'utc':now(),'command':['pdftotext','-layout',str(f),str(target)],'exit':cp.returncode,'stderr':cp.stderr.decode(errors='replace'),'output_sha256':sha(target.read_bytes()) if target.exists() else None})
(P/'text-job-log.json').write_text(json.dumps(logs,indent=2)+'\n')
inventory=[]
for f in sorted((P/'sources').iterdir()):
 inventory.append({'path':str(f),'sha256':sha(f.read_bytes()),'bytes':f.stat().st_size,'read_status':'See per-ID review_depth and MECHANISMS.md. Cached/converted is not proof-body read.'})
(P/'source-read-inventory.json').write_text(json.dumps({'utc':now(),'inventory':inventory,'limits':['Publisher tau journal returned empty 202, author deposit read instead; not a certified journal-equivalence check.','Unrelated 2107.06372 URL was fetched in error and not used; correct original flow source is 2512.17342.','Guessed product DOI returned 404 and supplies no evidence.','No GitHub API calls; public raw main projects.yml and candidate import index were read lawfully and matched a recent pinned snapshot. No complete current tree or global clearance.','LeanPool MaxFlowMinCut actual theorem bodies read: finite graph flow, not higher-dimensional simplicial statement. BrillNoetherGraphs entry is imports, not actual relevant proof bodies; no clearance for transmission loci.','Historical searches are text-based and bounded in saved output; binaries, alternate terminology and unread bodies remain gaps.']},indent=2)+'\n')
expected=(P/'reservation.sha256').read_text().strip(); actual=sha((P/'reservation.json').read_bytes());assert expected==actual
(P/'reservation-hashchecks.json').write_text(json.dumps({'before_utc':json.loads((P/'extraction-log.json').read_text())['utc'],'after_utc':now(),'before':expected,'expected':expected,'after':actual,'pass':True,'reservation_untouched':True,'exact_ids':list(map(int,d))},indent=2)+'\n')
(P/'resource-final-log.json').write_text(json.dumps({'utc':now(),'script':str(P/'finalize.py'),'cpu_limit_seconds':120,'wall_timeout_seconds':140,'AS_limit_bytes':6*1024**3,'affinity_cpus':sorted(os.sched_getaffinity(0)),'elapsed_seconds':time.monotonic()-start,'children_completed':True,'no_Lean_solver_or_search_execution':True,'limitation':'Earlier extraction/history/fetch jobs set CPU and AS limits and timeout; rg thread count was not explicitly pinned in those earlier scripts. All completed; no heavy numerical jobs.'},indent=2)+'\n')
